import { Component, input } from '@angular/core';
import { NzAffixModule } from 'ng-zorro-antd/affix';
import { NzWatermarkModule } from 'ng-zorro-antd/watermark';

/** hrm-affix — ghim phần tử khi cuộn, bọc nz-affix. Nội dung qua content.
 *  Ghim đầu khung nhìn: [offsetTop]. Ghim đáy: [offsetBottom]. */
@Component({
  selector: 'hrm-affix',
  imports: [NzAffixModule],
  template: `<nz-affix [nzOffsetTop]="offsetTop()" [nzOffsetBottom]="offsetBottom()"><ng-content /></nz-affix>`,
  host: { class: 'hrm-affix' },
})
export class HrmAffix {
  readonly offsetTop = input<number | null>(null);
  readonly offsetBottom = input<number | null>(null);
}

/** hrm-watermark — chèn watermark (bảo mật tài liệu HRM), bọc nz-watermark.
 *  `image` (URL logo/ảnh) ưu tiên hơn `content` (chữ). Dùng logo thương hiệu:
 *  <hrm-watermark image="/assets/vnr-logo.svg" [width]="180" [height]="38"> */
@Component({
  selector: 'hrm-watermark',
  imports: [NzWatermarkModule],
  template: `
    <nz-watermark
      [nzContent]="image() ? '' : content()"
      [nzImage]="image()"
      [nzWidth]="width()"
      [nzHeight]="height()"><ng-content /></nz-watermark>`,
  host: { class: 'hrm-watermark' },
})
export class HrmWatermark {
  readonly content = input<string | string[]>('');
  readonly image = input('');
  readonly width = input(120);
  readonly height = input(64);
}
